<script src="https://cdn.datatables.net/1.13.8/js/dataTables.bootstrap5.min.js"></script>
<script>
document.addEventListener('DOMContentLoaded', function () {
    if (!window.jQuery || !jQuery.fn.DataTable) return;
    var table = jQuery('#centersTable').DataTable({
        processing: true, serverSide: true, pageLength: 15, lengthMenu: [10, 15, 25, 50],
        ajax: '{{ route('centers.data') }}',
        columns: [
            {data: 'center', name: 'name'}, {data: 'mfi_badge', name: 'mfi'},
            {data: 'center_chief', name: 'center_chiefs_count', orderable: false, searchable: false},
            {data: 'added', name: 'created_at'}, {data: 'actions', orderable: false, searchable: false}
        ],
        order: [[0, 'asc']],
        language: { processing: 'Loading centers…', emptyTable: 'No centers yet.', zeroRecords: 'No matching centers found.' }
    });
    jQuery('#centerSearch').on('input', function () { table.search(this.value).draw(); });
    jQuery('#centersTable').on('click', '.center-edit', function () {
        var center = table.row(jQuery(this).closest('tr')).data();
        if (!center) return;
        document.getElementById('centerEditForm').action = '{{ url('/centers') }}/' + center.id;
        document.getElementById('centerEditName').value = center.name || '';
        document.getElementById('centerEditMfi').value = center.mfi || '';
        bootstrap.Modal.getOrCreateInstance(document.getElementById('centerEditModal')).show();
    });
});
</script>
@endsection
